public class InnerReplicatorKafkaClusterClientAuthenticationFactory(Action<Humidifier.MSK.ReplicatorTypes.KafkaClusterClientAuthentication> factoryAction = null) : SubResourceFactory<Humidifier.MSK.ReplicatorTypes.KafkaClusterClientAuthentication>
{

    internal InnerReplicatorKafkaClusterSaslOAuthBearerAuthenticationFactory SaslOAuthBearerFactory { get; set; }

    internal InnerReplicatorKafkaClusterMtlsAuthenticationFactory MTLSFactory { get; set; }

    internal InnerReplicatorKafkaClusterSaslScramAuthenticationFactory SaslScramFactory { get; set; }

    protected override Humidifier.MSK.ReplicatorTypes.KafkaClusterClientAuthentication Create()
    {
        var kafkaClusterClientAuthenticationResult = CreateKafkaClusterClientAuthentication();
        factoryAction?.Invoke(kafkaClusterClientAuthenticationResult);

        return kafkaClusterClientAuthenticationResult;
    }

    private Humidifier.MSK.ReplicatorTypes.KafkaClusterClientAuthentication CreateKafkaClusterClientAuthentication()
    {
        var kafkaClusterClientAuthenticationResult = new Humidifier.MSK.ReplicatorTypes.KafkaClusterClientAuthentication();

        return kafkaClusterClientAuthenticationResult;
    }
    public override void CreateChildren(Humidifier.MSK.ReplicatorTypes.KafkaClusterClientAuthentication result)
    {
        base.CreateChildren(result);

        result.SaslOAuthBearer ??= SaslOAuthBearerFactory?.Build();
        result.MTLS ??= MTLSFactory?.Build();
        result.SaslScram ??= SaslScramFactory?.Build();
    }

} // End Of Class

